mapper.select:
select IFNULL(cci.data_rate,0) + IFNULL(caseInfo.data_rate,0) + IFNULL(cii.data_rate,0) + IFNULL(cai.data_rate,0) total , caseInfo.is_intention isIntention,caseInfo.case_progress caseProgress ,cci.*
from crm_customer_info cci,
crm_case_info caseInfo,
crm_injury_info cii,
crm_accident_info cai
where
1=1
AND cci.id=caseInfo.customer_id
AND cci.id = cii.customer_id
AND cci.id = cai.customer_id

    and cci.org_id = #{orgId,jdbcType=BIGINT}


    and cci.cc_id = #{ccId,jdbcType=BIGINT}


    and cci.user_name = #{userName,jdbcType=VARCHAR}


    and caseInfo.is_intention = #{isIntention}


    and caseInfo.case_progress = #{caseProgress}


    ORDER BY cci.create_time DESC


    ORDER BY cci.create_time DESC


    ORDER BY cci.user_name DESC

 LIMIT #{pageIndex} , #{pageSize}

select count(cci.id)
from crm_customer_info cci,
crm_case_info caseInfo,
crm_injury_info cii,
crm_accident_info cai
where
1=1
AND cci.id=caseInfo.customer_id
AND cci.id = cii.customer_id
AND cci.id = cai.customer_id

    and cci.org_id = #{orgId,jdbcType=BIGINT}


    and cci.cc_id = #{ccId,jdbcType=BIGINT}


    and cci.user_name = #{userName,jdbcType=VARCHAR}


    and caseInfo.is_intention = #{isIntention}


    and caseInfo.case_progress = #{caseProgress}


    ORDER BY cci.create_time DESC


    ORDER BY cci.create_time DESC


    ORDER BY cci.user_name DESC

SELECT * FROM( SELECT cci.id, cci.user_name userName, caseInfo.is_intention isIntention, caseInfo.case_progress caseProgress, caseInfo.case_source caseSource, ccf.follow_time followTime, ccf.next_follow_time nextFollowTime, cci.cc_name ccName, cci.org_name orgName, cci.update_time updateTime, ccf.follow_desc followDesc, cci.family_address familyAddress, cci.user_phone userPhone FROM crm_customer_info cci LEFT JOIN crm_case_info caseInfo ON cci.id=caseInfo.customer_id LEFT JOIN crm_customer_follows ccf ON cci.id=ccf.customer_id WHERE 1=1
AND caseInfo.case_progress = #{caseProgress}
AND caseInfo.case_source = #{caseSource}
AND cci.org_id=#{orgId}
AND cci.cc_id=#{ccId}
ORDER BY ccf.create_time DESC ) a GROUP BY a.id LIMIT #{pageIndex} , #{pageSize}

SELECT
count(1)
FROM
crm_customer_info cci LEFT JOIN
crm_case_info caseInfo ON cci.id=caseInfo.customer_id
WHERE
1=1

    AND caseInfo.case_progress = #{caseProgress}


    AND caseInfo.case_source = #{caseSource}


    AND cci.org_id=#{orgId}


    AND cci.cc_id=#{ccId}
